mapper.insert:
INSERT INTO sys_role
("name", description, status, create_time, update_time, "delete", workspace_id, menu_keys, is_admin)
VALUES (#{item.name}, #{item.description}, true, now(), now(), false, #{item.workspaceId}, #{item.menuKeys},false);

mapper.select:
select distinct cost
from sys_organize
where society_id = #{id}

select ( select array_to_string(ARRAY(SELECT unnest(array_agg( distinct t.user_name))),',') from ( select su.user_name from sys_user su left join sys_user_roles sur on su.id::VARCHAR = sur.user_id and su.delete = false and su.status = true and sur."type" = 'Cybertron' where sur.role_id = sr.id union all select su.user_name from ad_tb_upp_nature_2 su left join sys_user_roles sur on su.user_name = sur.user_id and sur."type" = 'ADFS' where sur.role_id = sr.id ) as t ) as users, sr.id as id, sr.name as name, sr.description as description, sr.status as status, to_char( sr.create_time AT TIME ZONE 'UTC-8','YYYY-MM-DD hh24:mi:ss') as create_time, to_char( sr.update_time AT TIME ZONE 'UTC-8','YYYY-MM-DD hh24:mi:ss') as update_time, delete as delete, internal as internal, workspace_id as workspace_id, menu_keys as menu_keys, is_admin as is_admin from sys_role sr
delete = false
and sr.id = #{item.id}
and sr.name like '%'||#{item.name}||'%'
and sr.workspace_id = #{item.workspaceId}
order by sr.create_time desc

select count(0) from sys_role
delete = false
and id = #{item.id}
and name like '%'||#{item.name}||'%'
and workspace_id = #{item.workspaceId}

select * from sys_role where name = #{name} and delete = false

    and id != #{roleId}


    and workspace_id = #{workspaceId}

limit 1
